func TestDecodeCount(t *testing.T) {
 for _,tc:=range []struct{input string;want int}{{`{"count":3}`,3},{`{}`,0}} {if got,e:=decodeCount([]byte(tc.input));e!=nil||got!=tc.want{t.Fatal(got,e)}}
