func TestMetric(t *testing.T) {
 for _,v:=range []float64{3.5,0} { bytes,e:=encodeMetric("a\"b",v);if e!=nil {t.Fatal(e)};var got struct{Name string;Value float64};if e=json.Unmarshal(bytes,&got);e!=nil||got.Name!="a\"b"||got.Value!=v {t.Fatal(string(bytes),e)} }
