http-greet.tests:
func TestGreeting(t *testing.T) {
 for _,tc:=range []struct{method,path string;status int;body string}{{"GET","/hello?name=Ada",200,"Hello, Ada!"},{"GET","/hello?name=%20Ada%20",200,"Hello, Ada!"},{"GET","/hello?name=",400,"name required\n"},{"POST","/hello?name=Ada",405,"method\n"},{"GET","/other",404,"404 page not found\n"}} {
 rec:=httptest.NewRecorder();greet(rec,httptest.NewRequest(tc.method,tc.path,nil));res:=rec.Result();body,e:=io.ReadAll(res.Body);res.Body.Close();if e!=nil||res.StatusCode!=tc.status||string(body)!=tc.body {t.Fatal(tc, res.StatusCode,string(body),e)}
 if tc.status==200&&res.Header.Get("Content-Type")!="text/plain; charset=utf-8" {t.Fatal(res.Header)}
 if tc.status==405&&res.Header.Get("Allow")!="GET" {t.Fatal(res.Header)}
 }
}

context-receive.tests:
func TestReceive(t *testing.T) {
 jobs:=make(chan string,1);jobs<-"work";if v,e:=receiveJob(context.Background(),jobs);v!="work"||e!=nil {t.Fatal(v,e)}
 jobs<-"";if v,e:=receiveJob(context.Background(),jobs);v!=""||e!=nil {t.Fatal(v,e)}
 ctx,cancel:=context.WithCancel(context.Background());cancel();jobs<-"ready";if _,e:=receiveJob(ctx,jobs);!errors.Is(e,context.Canceled) {t.Fatal(e)}
 close(jobs);<-jobs;if _,e:=receiveJob(context.Background(),jobs);e==nil {t.Fatal("closed accepted")}
 waiting,c:=context.WithCancel(context.Background());done:=make(chan error,1);go func(){_,e:=receiveJob(waiting,make(chan string));done<-e}();c();select{case e:=<-done:if !errors.Is(e,context.Canceled){t.Fatal(e)};case <-time.After(time.Second):t.Fatal("blocked worker")}
}

context-deadline.tests:
func TestBudget(t *testing.T) {
 var child context.Context
 if e:=withinBudget(context.Background(),time.Hour,func(ctx context.Context)error{child=ctx;if _,ok:=ctx.Deadline();!ok{t.Fatal("no deadline")};return nil});e!=nil{t.Fatal(e)}
 if !errors.Is(child.Err(),context.Canceled){t.Fatal("child not released")}
 sentinel:=errors.New("work failed");if e:=withinBudget(context.Background(),time.Hour,func(context.Context)error{return sentinel});!errors.Is(e,sentinel){t.Fatal(e)}
 if e:=withinBudget(context.Background(),0,func(context.Context)error{t.Fatal("called invalid work");return nil});e==nil{t.Fatal("zero accepted")}
 expired,c:=context.WithDeadline(context.Background(),time.Unix(0,0));defer c();if e:=withinBudget(expired,time.Hour,func(context.Context)error{t.Fatal("called expired work");return nil});!errors.Is(e,context.DeadlineExceeded){t.Fatal(e)}
}

sync-counter.tests:
func TestCounter(t *testing.T) {
 var c Counter;var wg sync.WaitGroup
 for i:=0;i<20;i++ {wg.Add(1);go func(){defer wg.Done();if e:=c.Add(1);e!=nil{t.Error(e)}}()};wg.Wait()
 if c.Value()!=20 {t.Fatal(c.Value())};if e:=c.Add(0);e!=nil||c.Value()!=20{t.Fatal(e,c.Value())}
 if e:=c.Add(-1);e==nil||c.Value()!=20{t.Fatal(e,c.Value())}
}

files-lines.tests:
func TestLines(t *testing.T) {
 path:=filepath.Join(t.TempDir(),"input.txt")
 for _,tc:=range []struct{input string;want []string}{{"one\n  \ntwo\n",[]string{"one","two"}},{"",[]string{}}} {if e:=os.WriteFile(path,[]byte(tc.input),0600);e!=nil{t.Fatal(e)};got,e:=readLines(path);if e!=nil||!reflect.DeepEqual(got,tc.want){t.Fatal(got,e)}}
 if e:=os.WriteFile(path,[]byte(strings.Repeat("x",100000)),0600);e!=nil{t.Fatal(e)};if _,e:=readLines(path);e==nil{t.Fatal("oversize line accepted")}
 if _,e:=readLines(path+"-missing");!os.IsNotExist(e){t.Fatal(e)}
}

