func TestWrite(t *testing.T) {
 dir:=t.TempDir();path:=filepath.Join(dir,"report.txt")
 for _,want:=range []string{"report\n",""} {if e:=writeReport(path,want);e!=nil{t.Fatal(e)};got,e:=os.ReadFile(path);if e!=nil||string(got)!=want{t.Fatal(string(got),e)}}
 if e:=writeReport(filepath.Join(dir,"missing","report"),"x");e==nil{t.Fatal("missing parent accepted")}
 if e:=writeReport(dir,"x");e==nil{t.Fatal("directory accepted")}
}
